/**
 * Versioned, presentation-independent capability observation.
 */
public struct CapabilityStatus: Equatable, Hashable {
    public var id: String
    public var compiled: Bool
    public var configured: Bool
    public var availability: CapabilityAvailability
    public var maturity: CapabilityMaturity

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(id: String, compiled: Bool, configured: Bool, availability: CapabilityAvailability, maturity: CapabilityMaturity) {
        self.id = id
        self.compiled = compiled
        self.configured = configured
        self.availability = availability
        self.maturity = maturity
    }




