@_documentation(visibility: private)
#endif
public struct FfiConverterTypeCapabilityAvailability: FfiConverterRustBuffer {
    typealias SwiftType = CapabilityAvailability

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> CapabilityAvailability {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        case 1: return .available

        case 2: return .degraded

        case 3: return .unavailable

        case 4: return .unsupported

        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: CapabilityAvailability, into buf: inout [UInt8]) {
        switch value {


        case .available:
            writeInt(&buf, Int32(1))


        case .degraded:
            writeInt(&buf, Int32(2))


        case .unavailable:
            writeInt(&buf, Int32(3))


        case .unsupported:
            writeInt(&buf, Int32(4))

        }
    }
}


